using System;using System.IO;using System.Collections.Generic;using System.Reflection;using System.Linq;using UnityEngine;using EchoSphere.Core;using EchoSphere.Runtime;
public static class ArtifactProtocolProcAcceptance { public static object Main(){
const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;var r=UnityEngine.Object.FindAnyObjectByType<EchoSphereRuntime>();var t=r.GetType();var names=new[]{"_runEconomy","_networkState","_mainMenu","_paused","_userPaused","_resonanceGeometryType","_resonanceCharge","_resonanceEventActive","_timeStopTimer","_combo","_artifactProtocolHitCounters"};var old=new Dictionary<string,object>();foreach(var n in names)old[n]=t.GetField(n,F).GetValue(r);var owned=(List<string>)t.GetField("_ownedArtifacts",F).GetValue(r);var oldOwned=owned.ToArray();var spheres=(List<SphereAttackAgent>)t.GetField("_spheres",F).GetValue(r);var oldSpheres=spheres.ToArray();var enemies=(List<EnemyAgent2D>)t.GetField("_enemies",F).GetValue(r);var oldEnemies=enemies.ToArray();var mods=(Dictionary<string,int>)t.GetField("_sphereMods",F).GetValue(r);var oldMods=new Dictionary<string,int>(mods);var core=(PlayerCoreController2D)t.GetField("_playerCore",F).GetValue(r);var player=RunSnapshotCodec.Capture(core);var rng=(SeededRng)t.GetField("_rng",F).GetValue(r);uint originalRng=rng.State;var created=new List<GameObject>();int checks=0;
void Set(string n,object v)=>t.GetField(n,F).SetValue(r,v);void Check(bool v,string why){checks++;if(!v)throw new Exception(why);}
try{owned.Clear();owned.AddRange(ArtifactRewardRules.Catalog(true).Select(x=>x.Id));spheres.Clear();enemies.Clear();Set("_runEconomy",RunEconomyRules.Create(1));Set("_mainMenu",false);Set("_paused",false);Set("_userPaused",false);Set("_resonanceGeometryType",SphereNetworkFormation.Ring);Set("_timeStopTimer",2f);Set("_combo",5);mods["fire"]=1;
var types=new[]{SphereId.Standard,SphereId.Sniper,SphereId.Shotgun,SphereId.Chain,SphereId.Aura,SphereId.Orbital,SphereId.Pulse,SphereId.Gravity,SphereId.Void,SphereId.Prism};for(int i=0;i<types.Length;i++){var go=new GameObject("Protocol owner fixture");created.Add(go);go.transform.position=new Vector3(Mathf.Cos(i*Mathf.PI/5),Mathf.Sin(i*Mathf.PI/5));var s=go.AddComponent<SphereAttackAgent>();s.Initialize(r,core.transform,types[i],12);spheres.Add(s);}var state=new SphereNetworkState();for(int i=0;i<10;i++)state.Links.Add(new SphereNetworkLink(i,(i+1)%10,1));Set("_networkState",state);
foreach(var protocol in ArtifactProtocolRules.Protocols){core.SetMaxHpForNewRun(1000);core.SetShieldCharges(0);core.SpendHp(20);Set("_resonanceCharge",0f);Set("_resonanceEventActive",false);var go=new GameObject("Protocol target fixture");created.Add(go);go.transform.position=new Vector3(3,0);var enemy=go.AddComponent<EnemyAgent2D>();enemy.Initialize(r,core.transform,10000,0,1,"wisp","",true);enemies.Add(enemy);SphereId type=protocol.Id=="void_horizon_protocol"?SphereId.Void:protocol.Id=="hunter_doctrine_protocol"?SphereId.Sniper:protocol.Id=="pulse_engineering_protocol"?SphereId.Pulse:protocol.Id=="status_circuit_protocol"||protocol.Id=="prism_dominion_protocol"?SphereId.Prism:SphereId.Standard;var owner=spheres.Single(s=>s.Type==type);typeof(SphereAttackAgent).GetField("_attackTimer",F).SetValue(owner,10f);
// Group condition needs four living targets.
while(enemies.Count<4){var other=new GameObject("Protocol group fixture");created.Add(other);var e=other.AddComponent<EnemyAgent2D>();e.Initialize(r,core.transform,10000,0);enemies.Add(e);}
int cadence=ArtifactProtocolRules.HitCadence(protocol.Id);var counters=new Dictionary<string,int>{{protocol.Id,cadence-1}};Set("_artifactProtocolHitCounters",counters);float hp=core.CurrentHp,targetHp=enemy.CurrentHp;Vector3 pos=enemy.transform.position;Check((bool)t.GetMethod("IsArtifactProtocolCurrentlyActive",F).Invoke(r,new object[]{protocol}),"protocol gate "+protocol.Id);r.ApplyCampaignArtifactProtocolHit(owner,enemy,100,true);Check(counters[protocol.Id]==0,"protocol executed "+protocol.Id);
switch(protocol.Id){case "triangle_resonance":case "geometry_circuit":Check((float)t.GetField("_resonanceCharge",F).GetValue(r)>0,"resonance effect");break;case "sphere_relay":case "prism_dominion_protocol":Check((float)typeof(SphereAttackAgent).GetField("_attackTimer",F).GetValue(owner)<10,"attack advance");break;case "critical_echo":case "core_forge_protocol":Check(core.CurrentHp>hp,"heal effect");break;case "void_horizon_protocol":case "status_circuit_protocol":Check(enemy.MovementSlowMultiplier<1,"slow effect");break;case "temporal_fold_protocol":Check(enemy.IsFrozen,"freeze effect");break;case "hunter_doctrine_protocol":Check(Math.Abs(targetHp-enemy.CurrentHp-25f)<.001f,"exact additional strike");break;case "pulse_engineering_protocol":Check(enemy.transform.position!=pos,"knockback effect");break;case "network_legacy_protocol":Check(core.ShieldCharges==1,"shield effect");break;}
Set("_runEconomy",null);counters[protocol.Id]=cadence-1;r.ApplyCampaignArtifactProtocolHit(owner,enemy,100,true);Check(counters[protocol.Id]==cadence-1,"legacy proc disabled");Set("_runEconomy",RunEconomyRules.Create(1));}
Check(EchoSphere.Presentation.NativeRunCatalog.Instance.GetSets(true).Count==20,"twenty campaign sets");Check(EchoSphere.Presentation.NativeRunCatalog.Instance.GetSets(false).Count==12,"twelve legacy sets");
foreach(var set in CampaignArtifactSets.All){owned.Clear();owned.AddRange(set.Requires);core.SetMaxHpForNewRun(1000);core.SetShieldCharges(0);core.SpendHp(600);Set("_resonanceCharge",0f);Set("_resonanceEventActive",false);var go=new GameObject("Set target fixture");created.Add(go);go.transform.position=new Vector3(3,0);var enemy=go.AddComponent<EnemyAgent2D>();enemy.Initialize(r,core.transform,10000,0);enemies.Add(enemy);var owner=spheres.Single(x=>x.Type==(set.Id=="frozen_optics"?SphereId.Sniper:set.Id=="wave_rotor"?SphereId.Pulse:SphereId.Standard));typeof(SphereAttackAgent).GetField("_attackTimer",F).SetValue(owner,10f);string key="set:"+set.Id;var counters=new Dictionary<string,int>{{key,set.Cadence-1}};Set("_artifactProtocolHitCounters",counters);float hp=core.CurrentHp,ehp=enemy.CurrentHp;var pos=enemy.transform.position;Check(set.Complete(owned),"set requirements "+set.Id);r.ApplyCampaignArtifactProtocolHit(owner,enemy,100,true);Check(counters[key]==0,"set counter executed "+set.Id);
switch(set.Effect){case "shield":Check(core.ShieldCharges==1,"set shield");break;case "advance":Check((float)typeof(SphereAttackAgent).GetField("_attackTimer",F).GetValue(owner)<10,"set attack advance");break;case "freeze":Check(enemy.IsFrozen,"set freeze");break;case "knockback":Check(enemy.transform.position!=pos,"set knockback");break;case "heal":Check(core.CurrentHp>hp,"set heal");break;case "resonance":Check((float)t.GetField("_resonanceCharge",F).GetValue(r)>0,"set charge");break;case "strike":Check(Math.Abs(ehp-enemy.CurrentHp-15f)<.001f,"exact set extra hit");break;}
Set("_runEconomy",null);counters[key]=set.Cadence-1;r.ApplyCampaignArtifactProtocolHit(owner,enemy,100,true);Check(counters[key]==set.Cadence-1,"legacy no new set proc");Set("_runEconomy",RunEconomyRules.Create(1));}
owned.Clear();owned.AddRange(ArtifactRewardRules.Catalog(true).Select(x=>x.Id));var complete=(HashSet<string>)t.GetMethod("NativeLiveCompletedSets",F).Invoke(r,null);Check(complete.Count==20,"all twenty sets visible as complete");
var savedCounters=new Dictionary<string,int>{{"set:unstable_echo",7}};Set("_artifactProtocolHitCounters",savedCounters);var snapshot=RunSnapshotCodec.Capture(r,field=>field.Name=="_artifactProtocolHitCounters");Set("_artifactProtocolHitCounters",new Dictionary<string,int>());RunSnapshotCodec.Restore(snapshot,t,r);var restored=(Dictionary<string,int>)t.GetField("_artifactProtocolHitCounters",F).GetValue(r);Check(restored["set:unstable_echo"]==7,"saved proc counters roundtrip");r.ApplyCampaignArtifactProtocolHit(spheres[0],enemies[0],100,false);Check(restored["set:unstable_echo"]==7,"secondary hits do not proc");r.ApplyCampaignArtifactProtocolHit(spheres[0],enemies[0],0,true);Check(restored["set:unstable_echo"]==7,"zero damage does not proc");
var result=new{result="PASS",checks,scope="Actual twelve protocols,eight sets,side effects,counter persistence,proc guards and legacy isolation;borrowed state restored,no prefs writes"};File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../Library/artifact-protocol-procs-acceptance.json")),Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;
}finally{foreach(var n in names)Set(n,old[n]);owned.Clear();owned.AddRange(oldOwned);spheres.Clear();spheres.AddRange(oldSpheres);enemies.Clear();enemies.AddRange(oldEnemies);mods.Clear();foreach(var pair in oldMods)mods[pair.Key]=pair.Value;RunSnapshotCodec.Restore(player,core.GetType(),core);rng.RestoreState(originalRng);foreach(var go in created)UnityEngine.Object.Destroy(go);}}
}
